<script setup lang="ts">
import { computed, ref, watch, onMounted } from 'vue';
import { encodeQR, type QRErrorLevel } from './internal/qr';
import './styles/theme.css'; import './styles/qrcode.css';
const props = withDefaults(defineProps<{ value: string; size?: number; type?: 'svg' | 'canvas'; errorLevel?: QRErrorLevel; color?: string; bgColor?: string; icon?: string; iconSize?: number; bordered?: boolean; margin?: number; status?: 'active' | 'expired' | 'loading' | 'scanned'; title?: string }>(), { size: 160, type: 'svg', color: '#222438', bgColor: '#ffffff', bordered: true, margin: 2, status: 'active', title: '二维码' });
const emit = defineEmits<{ refresh: [] }>(); const canvas = ref<HTMLCanvasElement | null>(null);
const matrix = computed(() => { try { return encodeQR(props.value, props.errorLevel ?? (props.icon ? 'H' : 'M')); } catch { return null; } }); const total = computed(() => (matrix.value?.size ?? 0) + props.margin * 2); const iconSize = computed(() => props.iconSize ?? Math.round(props.size * 0.22)); const iconUnits = computed(() => iconSize.value * total.value / props.size); const plateUnits = computed(() => (iconSize.value + 8) * total.value / props.size);
const path = computed(() => { const parts: string[] = []; matrix.value?.modules.forEach((row, y) => { let x = 0; while (x < row.length) { if (!row[x]) { x++; continue; } let run = 0; while (row[x + run]) run++; parts.push(`M${x + props.margin} ${y + props.margin}h${run}v1h-${run}z`); x += run; } }); return parts.join(''); });
let generation = 0;
function draw() { const version = ++generation; if (props.type !== 'canvas' || !canvas.value || !matrix.value) return; const element = canvas.value, ratio = devicePixelRatio || 1; element.width = props.size * ratio; element.height = props.size * ratio; const ctx = element.getContext('2d'); if (!ctx) return; const scale = props.size / total.value * ratio; ctx.fillStyle = props.bgColor; ctx.fillRect(0, 0, element.width, element.height); ctx.fillStyle = props.color; matrix.value.modules.forEach((row, y) => row.forEach((dark, x) => { if (dark) ctx.fillRect(Math.floor((x + props.margin) * scale), Math.floor((y + props.margin) * scale), Math.ceil(scale), Math.ceil(scale)); })); if (props.icon) { const image = new window.Image(); image.crossOrigin = 'anonymous'; image.onload = () => { if (generation !== version) return; const size = iconSize.value * ratio, offset = (element.width - size) / 2; ctx.fillStyle = props.bgColor; ctx.fillRect(offset - 4 * ratio, offset - 4 * ratio, size + 8 * ratio, size + 8 * ratio); ctx.drawImage(image, offset, offset, size, size); }; image.src = props.icon; } }
onMounted(() => { draw(); watch(() => [props.value, props.type, props.size, props.errorLevel, props.color, props.bgColor, props.icon, props.iconSize, props.margin], draw, { flush: 'post' }); });
</script>
<template><div :class="['at-qrcode', { 'at-qrcode--bordered': bordered, 'at-qrcode--masked': status !== 'active' }]" :style="{ width: `${size}px`, height: `${size}px`, backgroundColor: bgColor }" role="img" :aria-label="`${title}：${value}`"><div v-if="!matrix" class="at-qrcode__error">内容过长，无法生成</div><svg v-else-if="type === 'svg'" class="at-qrcode__svg" :viewBox="`0 0 ${total} ${total}`" :width="size" :height="size" shape-rendering="crispEdges" aria-hidden="true"><rect :width="total" :height="total" :fill="bgColor" /><path :d="path" :fill="color" /><template v-if="icon"><rect :x="(total - plateUnits) / 2" :y="(total - plateUnits) / 2" :width="plateUnits" :height="plateUnits" :rx="total / size * 3" :fill="bgColor" /><image :href="icon" :x="(total - iconUnits) / 2" :y="(total - iconUnits) / 2" :width="iconUnits" :height="iconUnits" preserveAspectRatio="xMidYMid slice" /></template></svg><canvas v-else ref="canvas" class="at-qrcode__canvas" :style="{ width: `${size}px`, height: `${size}px` }" aria-hidden="true" /><slot v-if="status !== 'active'" name="status" :status="status" :on-refresh="() => emit('refresh')"><div class="at-qrcode__status" role="status"><template v-if="status === 'loading'"><span class="at-qrcode__spinner" aria-hidden="true" /><span>加载中…</span></template><template v-if="status === 'expired'"><span>二维码已过期</span><button type="button" class="at-qrcode__refresh" @click="emit('refresh')">点击刷新</button></template><template v-if="status === 'scanned'"><span class="at-qrcode__check" aria-hidden="true">✓</span><span>已扫描</span></template></div></slot></div></template>
